var e=JSON.parse('[{"id":"03-a1b2c3d4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"EC2 instance families","difficulty":"easy","question":"A company needs EC2 instances for a memory-intensive in-memory database that requires 512 GB of RAM. Which instance family is most appropriate?","options":{"A":"C5 (Compute Optimized)","B":"R6i (Memory Optimized)","C":"P4d (Accelerated Computing)","D":"D3 (Storage Optimized)"},"correct":"B","explanation":"R-family (Memory Optimized) instances are designed for workloads that process large data sets in memory, such as in-memory databases, real-time big data analytics, and high-performance computing. R6i instances provide up to 768 GB of RAM.","distractors":{"A":"C5 instances are compute-optimized for CPU-bound workloads, not memory-intensive applications.","C":"P4d instances are GPU-accelerated for machine learning and HPC, not for general in-memory databases.","D":"D3 instances are storage-optimized with dense HDD storage for data warehousing, not memory-intensive databases."},"source_url":"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html","tags":["ec2","instance-families","memory-optimized"],"verified":true},{"id":"03-a1b2c3d5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"EC2 instance families","difficulty":"medium","question":"A financial services firm runs Monte Carlo simulations that require massive parallel floating-point computations. The workload is CPU-bound and needs the highest possible compute throughput per core. Which instance family should they choose?","options":{"A":"M6i (General Purpose)","B":"R6i (Memory Optimized)","C":"C6i (Compute Optimized)","D":"I3 (Storage Optimized)"},"correct":"C","explanation":"C-family (Compute Optimized) instances deliver the highest compute performance per dollar for CPU-intensive workloads such as scientific modeling, batch processing, high-performance computing, and media transcoding. The C6i uses Intel Ice Lake processors optimized for sustained compute.","distractors":{"A":"M6i is general-purpose with a balanced CPU/memory ratio, not optimized for maximum compute throughput.","B":"R6i prioritizes memory over compute and is more expensive per vCPU than C-family instances.","D":"I3 instances optimize for NVMe storage I/O, not floating-point compute throughput."},"source_url":"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/compute-optimized-instances.html","tags":["ec2","instance-families","compute-optimized"],"verified":true},{"id":"03-a1b2c3d6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"EC2 instance families","difficulty":"medium","question":"A deep learning team needs to train large neural networks. They require high GPU memory bandwidth and fast GPU-to-GPU communication for distributed training across multiple nodes. Which instance family is designed for this use case?","options":{"A":"G5 (GPU instances)","B":"P4d (Accelerated Computing)","C":"C6g (Compute Optimized, Graviton)","D":"Inf1 (Inferentia)"},"correct":"B","explanation":"P4d instances feature NVIDIA A100 GPUs with NVLink and 400 Gbps EFA (Elastic Fabric Adapter) networking for ultra-low latency GPU-to-GPU communication. They are purpose-built for distributed deep learning training at scale. Each P4d instance has 8 A100 GPUs with 320 GB of GPU memory.","distractors":{"A":"G5 instances are for graphics-intensive applications and ML inference; they lack the high-bandwidth GPU interconnects needed for large distributed training.","C":"C6g uses Graviton3 ARM CPUs with no GPU acceleration, unsuitable for GPU-based deep learning training.","D":"Inf1 uses AWS Inferentia chips optimized specifically for inference workloads, not training."},"source_url":"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/accelerated-computing-instances.html","tags":["ec2","instance-families","gpu","deep-learning"],"verified":true},{"id":"03-a1b2c3d7","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"EC2 instance families","difficulty":"hard","question":"An analytics platform needs to process large sequential log files from cold storage. The workload is I/O bound with massive sequential read throughput requirements and needs local NVMe storage to avoid network bottlenecks. Which instance family is most suitable?","options":{"A":"C5n (Compute Optimized with enhanced networking)","B":"I4i (Storage Optimized)","C":"R6id (Memory Optimized with local NVMe)","D":"X2idn (Memory Optimized, high I/O)"},"correct":"B","explanation":"I4i instances provide the highest local NVMe SSD storage density and throughput of any EC2 instance family, with up to 30 TB of NVMe storage and extremely high sequential read IOPS. They are designed for I/O-intensive workloads like NoSQL databases, data warehousing, and analytics requiring local high-throughput storage.","distractors":{"A":"C5n has enhanced 100 Gbps network bandwidth but does not provide local NVMe storage; it is for compute-intensive network-heavy workloads.","C":"R6id has local NVMe storage but is optimized for memory-intensive workloads; the I/O throughput is lower than I4i instances.","D":"X2idn is designed for very large in-memory databases (up to 24 TB RAM) and has high I/O, but at a much higher cost than I4i for a pure sequential-read use case."},"source_url":"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/storage-optimized-instances.html","tags":["ec2","instance-families","storage-optimized","nvme"],"verified":true},{"id":"03-a1b2c3d8","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"EC2 instance families","difficulty":"easy","question":"A startup wants to run a web application tier with a mix of moderate CPU and memory requirements. They want the best price-performance ratio for general workloads. Which instance family should they start with?","options":{"A":"M7g (General Purpose, Graviton3)","B":"C6i (Compute Optimized)","C":"R6i (Memory Optimized)","D":"P3 (GPU Accelerated)"},"correct":"A","explanation":"M-family (General Purpose) instances with Graviton3 processors (M7g) offer the best price-performance for general web and application workloads. Graviton3 instances provide up to 40% better price-performance than x86-based M instances. They are ideal when there is no specific CPU, memory, or I/O bottleneck.","distractors":{"B":"C6i over-provisions compute relative to what a balanced web application needs, increasing cost without benefit.","C":"R6i over-provisions memory relative to what a typical web application needs.","D":"P3 is GPU-accelerated for machine learning and is far too expensive for a general web application tier."},"source_url":"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/general-purpose-instances.html","tags":["ec2","instance-families","general-purpose","graviton"],"verified":true},{"id":"03-b1c2d3e4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"EC2 placement groups","difficulty":"medium","question":"A financial trading application requires the absolute lowest network latency between EC2 instances that need to communicate with each other. All instances run in a single Availability Zone. Which placement group strategy should be used?","options":{"A":"Spread placement group","B":"Partition placement group","C":"Cluster placement group","D":"No placement group (default)"},"correct":"C","explanation":"Cluster placement groups place instances physically close together within a single AZ on the same underlying hardware rack or adjacent racks. This provides the lowest possible network latency (single-digit microseconds) and highest network throughput (up to 100 Gbps with enhanced networking). They are ideal for HPC and low-latency inter-node communication.","distractors":{"A":"Spread placement groups ensure instances are placed on distinct hardware to reduce correlated failures, prioritizing availability over latency — the opposite of what is needed here.","B":"Partition placement groups spread instances across logical partitions on separate hardware racks, reducing correlated failures for distributed workloads, but not minimizing latency.","D":"Without a placement group, AWS makes no guarantee about physical proximity, leading to higher and more variable latency."},"source_url":"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/placement-groups.html","tags":["ec2","placement-groups","cluster","latency"],"verified":true},{"id":"03-b1c2d3e5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"EC2 placement groups","difficulty":"medium","question":"A company is deploying a distributed database that uses replication across 9 nodes. They want to minimize the blast radius of hardware failures — if a rack fails, only a subset of nodes should be affected. Which placement group strategy is most appropriate?","options":{"A":"Cluster placement group","B":"Spread placement group","C":"Partition placement group","D":"Availability Zone grouping without placement groups"},"correct":"C","explanation":"Partition placement groups divide instances into logical partitions, each on a separate set of hardware racks. A single rack failure only affects one partition. With up to 7 partitions per AZ and up to hundreds of instances per partition, they are designed exactly for distributed databases (Cassandra, HDFS, Kafka) where you want rack-aware replication — e.g., place 3 nodes in 3 different partitions.","distractors":{"A":"Cluster groups pack all instances together for low latency, meaning a hardware failure could take down multiple nodes simultaneously.","B":"Spread groups guarantee each instance is on distinct hardware but are limited to 7 instances per AZ — insufficient for 9 nodes.","D":"Without a placement group there is no guarantee about partition isolation; instances may share the same physical rack."},"source_url":"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/placement-groups.html#placement-groups-partition","tags":["ec2","placement-groups","partition","distributed-database"],"verified":true},{"id":"03-b1c2d3e6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"EC2 placement groups","difficulty":"easy","question":"A company runs 6 critical EC2 instances for a primary database cluster. Each instance must be isolated on separate physical hardware to eliminate correlated failures. Which placement group type ensures each instance is on distinct underlying hardware?","options":{"A":"Cluster placement group","B":"Partition placement group","C":"Spread placement group","D":"No placement group required"},"correct":"C","explanation":"Spread placement groups guarantee that each instance is placed on distinct underlying hardware (separate racks with separate power and network). This maximizes fault isolation — if one rack fails, only one instance is affected. Spread groups are limited to 7 instances per AZ per placement group.","distractors":{"A":"Cluster groups colocate instances for low latency but may place multiple instances on the same physical host or rack.","B":"Partition groups isolate partitions from each other but multiple instances within the same partition can share hardware.","D":"Without a spread placement group, AWS may place instances on the same physical host, creating a single point of failure."},"source_url":"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/placement-groups.html#placement-groups-spread","tags":["ec2","placement-groups","spread","fault-isolation"],"verified":true},{"id":"03-b1c2d3e7","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"EC2 placement groups","difficulty":"hard","question":"A solutions architect needs to deploy a 100-node HPC cluster that requires 100 Gbps between nodes AND the ability to survive a single rack failure with minimal impact. Which approach best balances low latency and resilience?","options":{"A":"Single cluster placement group across one AZ","B":"Multiple spread placement groups across multiple AZs","C":"A cluster placement group with partition-aware job scheduling","D":"Two partition placement groups, each within a cluster placement group"},"correct":"A","explanation":"For HPC workloads that require 100 Gbps inter-node bandwidth, a cluster placement group is required — it is the only way to achieve the enhanced networking bandwidth needed. The architect should use AWS-recommended Elastic Fabric Adapter (EFA) for MPI applications within the cluster group. While a single rack failure could affect multiple nodes, HPC workloads typically use checkpointing to handle failures rather than sacrificing the bandwidth needed for the simulation. Partition or spread groups would fragment bandwidth.","distractors":{"B":"Spreading across AZs introduces cross-AZ latency (1-3ms vs <1µs) and bandwidth constraints that make HPC infeasible.","C":"Partition-aware scheduling is a software concept; you cannot combine cluster and partition placement group behaviors in the same group.","D":"Cluster and partition placement groups are mutually exclusive in AWS — you cannot nest them."},"source_url":"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/placement-groups.html","tags":["ec2","placement-groups","hpc","efa"],"verified":true},{"id":"03-c1d2e3f4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"ECS EKS and Fargate","difficulty":"easy","question":"A team wants to run Docker containers without managing the underlying EC2 instances or clusters. They want AWS to handle all server provisioning, patching, and scaling. Which compute option should they choose?","options":{"A":"Amazon ECS on EC2","B":"Amazon EKS on EC2","C":"AWS Fargate","D":"AWS Batch"},"correct":"C","explanation":"AWS Fargate is a serverless compute engine for containers that eliminates the need to provision and manage servers. You define your container requirements (CPU, memory), and Fargate automatically provisions the right amount of compute. It works with both ECS and EKS and removes all cluster management overhead.","distractors":{"A":"ECS on EC2 requires managing EC2 instances including capacity, patching, and scaling — you are responsible for the underlying cluster.","B":"EKS on EC2 provides managed Kubernetes control plane but still requires you to manage EC2 worker nodes.","D":"AWS Batch is for batch computing workloads and orchestrates EC2 or Fargate resources, but it is not a general container-without-server-management solution."},"source_url":"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/AWS_Fargate.html","tags":["fargate","ecs","serverless","containers"],"verified":true},{"id":"03-c1d2e3f5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"ECS EKS and Fargate","difficulty":"medium","question":"A company already uses Kubernetes on-premises with Helm charts, custom operators, and Kubernetes-native tooling. They want to migrate to AWS while minimizing changes to their deployment workflows and tooling. Which AWS service should they use?","options":{"A":"Amazon ECS with Fargate","B":"Amazon EKS","C":"AWS App Runner","D":"AWS Lambda container images"},"correct":"B","explanation":"Amazon EKS (Elastic Kubernetes Service) provides a fully managed Kubernetes control plane that is compatible with standard Kubernetes tooling including kubectl, Helm, and custom operators. Teams can reuse existing Kubernetes manifests, Helm charts, and CI/CD pipelines with minimal changes, making EKS the natural migration path for Kubernetes-native workloads.","distractors":{"A":"ECS uses AWS-proprietary task definitions and service concepts that are not compatible with Kubernetes tooling like Helm or kubectl.","C":"App Runner is a fully managed service for web applications and APIs that abstracts away all container orchestration — Kubernetes tooling does not apply.","D":"Lambda container images run individual functions, not long-running Kubernetes-orchestrated services, and have no Kubernetes compatibility."},"source_url":"https://docs.aws.amazon.com/eks/latest/userguide/what-is-eks.html","tags":["eks","kubernetes","containers","migration"],"verified":true},{"id":"03-c1d2e3f6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"ECS EKS and Fargate","difficulty":"medium","question":"A company runs an ECS service with Fargate. During business hours, traffic can spike 10x in 5 minutes. They want the service to scale automatically based on CPU utilization. Which scaling mechanism should they configure?","options":{"A":"ECS Service Auto Scaling with a target tracking policy on ECSServiceAverageCPUUtilization","B":"EC2 Auto Scaling with a step scaling policy","C":"AWS Lambda scheduled scaling based on time of day","D":"Manual scaling by updating the ECS service desired count"},"correct":"A","explanation":"ECS Service Auto Scaling uses Application Auto Scaling to automatically adjust the desired task count. Target tracking policies continuously adjust scale-out/in to keep a metric (such as ECSServiceAverageCPUUtilization) at a specified target value. This is the recommended approach for ECS with Fargate because it responds dynamically to actual load without managing EC2 instances.","distractors":{"B":"EC2 Auto Scaling scales EC2 instances in an Auto Scaling group — it does not scale ECS Fargate tasks, which have no underlying EC2 instances to manage.","C":"Lambda scheduled scaling is for Lambda reserved concurrency, not ECS services; it is also time-based rather than load-based.","D":"Manual scaling requires human intervention and cannot respond quickly to sudden spikes in traffic."},"source_url":"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/service-auto-scaling.html","tags":["ecs","fargate","auto-scaling","target-tracking"],"verified":true},{"id":"03-c1d2e3f7","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"ECS EKS and Fargate","difficulty":"hard","question":"A microservices application runs 20 different ECS services. The team needs service discovery so that Service A can call Service B by a stable DNS name without hardcoding IP addresses. Which AWS feature enables this?","options":{"A":"Application Load Balancer with path-based routing","B":"AWS Cloud Map with ECS Service Discovery","C":"Amazon Route 53 private hosted zone with manual record management","D":"VPC Lattice with target groups"},"correct":"B","explanation":"AWS Cloud Map provides service discovery for ECS. When configured, ECS automatically registers task IP addresses and ports in Cloud Map. Other services can then use Cloud Map DNS names (e.g., service-b.local) or the Cloud Map API to discover healthy endpoints. ECS Service Discovery integrates natively and deregisters tasks when they stop.","distractors":{"A":"ALB with path-based routing adds a load balancer in front of each service, which works but is more expensive and adds latency compared to direct service-to-service communication via Cloud Map DNS.","C":"A manual Route 53 private hosted zone requires someone to update DNS records whenever tasks start or stop — it cannot do automatic registration/deregistration.","D":"VPC Lattice provides service-to-service connectivity with access controls but requires more configuration and is newer; Cloud Map is the native ECS service discovery solution."},"source_url":"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/service-discovery.html","tags":["ecs","cloud-map","service-discovery","microservices"],"verified":true},{"id":"03-d1e2f3g4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Lambda concurrency and scaling","difficulty":"easy","question":"A Lambda function processes real-time payment events. During a sale event, 5,000 requests arrive simultaneously. Without any configuration, what is the default behavior of Lambda for concurrent executions?","options":{"A":"Lambda queues excess requests and processes them sequentially","B":"Lambda automatically scales up to 1,000 concurrent executions by default per region","C":"Lambda rejects all requests beyond 100 concurrent executions","D":"Lambda scales to unlimited concurrent executions immediately"},"correct":"B","explanation":"By default, AWS Lambda provides 1,000 concurrent executions per AWS region (the regional concurrency limit). Lambda scales by adding new execution environments for each concurrent request. The initial burst limit is 3,000 concurrent executions (in most regions), scaling by 500 per minute thereafter, up to the regional limit.","distractors":{"A":"Lambda does not queue requests by default for synchronous invocations — excess requests receive a throttling error (429). Asynchronous invocations use an internal queue.","C":"There is no 100-concurrent-execution limit; the default regional limit is 1,000.","D":"Lambda does not scale to unlimited concurrency; the regional limit (default 1,000) is a hard ceiling unless you request a quota increase."},"source_url":"https://docs.aws.amazon.com/lambda/latest/dg/lambda-concurrency.html","tags":["lambda","concurrency","scaling","throttling"],"verified":true},{"id":"03-d1e2f3g5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Lambda concurrency and scaling","difficulty":"medium","question":"A company has a critical Lambda function that must always have capacity available to handle requests, even during a concurrency spike caused by other Lambda functions in the same account. Which feature guarantees a reserved pool of concurrent executions for this function?","options":{"A":"Provisioned Concurrency","B":"Reserved Concurrency","C":"Enhanced networking","D":"Lambda SnapStart"},"correct":"B","explanation":"Reserved Concurrency sets a maximum limit of concurrent executions for a specific function AND reserves that capacity from the regional pool so other functions cannot consume it. This guarantees the critical function always has its allocated concurrency available. If the function exceeds its reserved concurrency, it throttles rather than consuming shared capacity.","distractors":{"A":"Provisioned Concurrency keeps a number of execution environments pre-initialized (warmed up) to eliminate cold starts — it does not reserve capacity away from other functions in the account.","C":"Enhanced networking is an EC2 feature using SR-IOV; it does not apply to Lambda.","D":"Lambda SnapStart reduces cold start latency for Java functions by restoring a snapshot of an initialized execution environment — it does not reserve concurrency."},"source_url":"https://docs.aws.amazon.com/lambda/latest/dg/configuration-concurrency.html","tags":["lambda","reserved-concurrency","throttling"],"verified":true},{"id":"03-d1e2f3g6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Lambda concurrency and scaling","difficulty":"medium","question":"A Lambda function written in Java takes 8 seconds for a cold start due to JVM initialization and Spring Boot startup. This causes unacceptable latency for API consumers. Which Lambda feature can eliminate these cold start delays without changing the code?","options":{"A":"Reserved Concurrency set to a high value","B":"Provisioned Concurrency","C":"Lambda@Edge","D":"Lambda SnapStart for Java"},"correct":"D","explanation":"Lambda SnapStart for Java (on Corretto runtimes) takes a snapshot of the initialized execution environment after the init phase completes and caches it. When a new execution environment is needed, Lambda restores from the snapshot instead of re-initializing, reducing cold start times by up to 90%. This requires no code changes.","distractors":{"A":"Reserved Concurrency limits how many instances of a function can run concurrently — it does not keep environments warm or eliminate cold starts.","B":"Provisioned Concurrency also eliminates cold starts by pre-warming environments but costs more because you pay for idle warm environments 24/7. SnapStart is more cost-effective because it only restores on demand.","C":"Lambda@Edge runs Lambda functions at CloudFront edge locations — it does not address Java cold start latency."},"source_url":"https://docs.aws.amazon.com/lambda/latest/dg/snapstart.html","tags":["lambda","snapstart","cold-start","java"],"verified":true},{"id":"03-d1e2f3g7","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Lambda concurrency and scaling","difficulty":"hard","question":"A Lambda function processes SQS messages and has Reserved Concurrency set to 10. The SQS queue accumulates 1,000 messages. What happens when all 10 concurrent Lambda executions are busy and a new batch of messages arrives?","options":{"A":"Lambda automatically raises the reserved concurrency to handle the backlog","B":"The excess messages are dropped from the SQS queue","C":"Lambda throttles — messages remain in the SQS queue and are retried after the visibility timeout","D":"SQS triggers a DLQ immediately for the throttled messages"},"correct":"C","explanation":"When Lambda is throttled due to reserved concurrency limits, SQS messages are not lost. Lambda returns an error to SQS, and SQS makes the messages visible again after the visibility timeout expires. SQS then retries delivering those messages. This creates backpressure — the queue depth grows until Lambda can process the backlog. Messages go to the DLQ only after exceeding the maximum receive count.","distractors":{"A":"Lambda never auto-raises reserved concurrency — it is a hard limit you set manually. Auto-scaling concurrency is not a feature.","B":"SQS does not drop messages when Lambda throttles. Messages are requeued and retried.","D":"Messages go to the DLQ only after the `maxReceiveCount` is exceeded (e.g., after 3 failed retries), not immediately on throttling."},"source_url":"https://docs.aws.amazon.com/lambda/latest/dg/with-sqs.html","tags":["lambda","sqs","concurrency","throttling","dlq"],"verified":true},{"id":"03-e1f2g3h4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Lambda event sources","difficulty":"easy","question":"A company wants to run a Lambda function every 15 minutes to clean up expired database records. Which AWS service should trigger the Lambda function on this schedule?","options":{"A":"Amazon SNS with a retry policy","B":"Amazon EventBridge Scheduler","C":"AWS Step Functions state machine","D":"Amazon SQS with a delay queue"},"correct":"B","explanation":"Amazon EventBridge Scheduler (formerly CloudWatch Events rules) allows you to create cron or rate-based schedules to invoke Lambda functions. A rate expression like `rate(15 minutes)` triggers the function on the specified interval. It is the standard, cost-effective way to schedule recurring Lambda invocations.","distractors":{"A":"SNS delivers messages published by a publisher — it does not have a built-in scheduler to trigger events at fixed intervals.","C":"Step Functions can orchestrate Lambda functions but adds unnecessary complexity for a simple recurring schedule.","D":"SQS delay queues delay message delivery but cannot generate messages on a recurring schedule by themselves."},"source_url":"https://docs.aws.amazon.com/eventbridge/latest/userguide/eb-run-lambda-schedule.html","tags":["lambda","eventbridge","scheduling","event-sources"],"verified":true},{"id":"03-e1f2g3h5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Lambda event sources","difficulty":"medium","question":"A company streams clickstream events to a Kinesis Data Stream with 10 shards. They want to process each event with a Lambda function. What is the maximum number of Lambda invocations that can process records concurrently from this stream?","options":{"A":"1 Lambda invocation reading all shards at once","B":"10 concurrent Lambda invocations — one per shard","C":"100 concurrent Lambda invocations with parallelization factor","D":"Unlimited — Lambda scales independently of shard count"},"correct":"C","explanation":"By default, Lambda uses one concurrent invocation per Kinesis shard (10 in this case). However, with the Parallelization Factor setting (1–10), Lambda can invoke multiple concurrent executions per shard. With a parallelization factor of 10 across 10 shards, you get 100 concurrent Lambda invocations, increasing throughput without adding shards.","distractors":{"A":"Lambda creates one invocation per shard at minimum, so 10 shards means at least 10 concurrent invocations.","B":"One per shard is the default behavior without a parallelization factor configured, but the question asks for the maximum.","D":"Lambda concurrency for Kinesis is bounded by shard count multiplied by parallelization factor — it is not unlimited."},"source_url":"https://docs.aws.amazon.com/lambda/latest/dg/with-kinesis.html","tags":["lambda","kinesis","event-sources","parallelization"],"verified":true},{"id":"03-e1f2g3h6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Lambda event sources","difficulty":"medium","question":"A Lambda function is triggered by an SQS queue. The function occasionally fails and throws an exception. What happens to the failed message in the SQS queue if no DLQ is configured?","options":{"A":"The message is immediately deleted from the queue after the first failure","B":"The message becomes visible again after the visibility timeout and is retried up to the queue\'s maxReceiveCount","C":"SQS sends the message to an automatic fallback Lambda function","D":"The message is permanently retained in the queue until manually deleted"},"correct":"B","explanation":"When a Lambda function fails to process an SQS message (throws an exception), Lambda reports a failure to SQS. SQS makes the message visible again after the visibility timeout expires. SQS retries delivery up to the `maxReceiveCount` (default 4). After exceeding `maxReceiveCount` without a DLQ configured, the message is deleted from the queue (lost). Always configure a DLQ to capture failed messages.","distractors":{"A":"The message is not deleted on first failure — it is retried until maxReceiveCount is exceeded.","C":"There is no automatic fallback Lambda function in SQS — the DLQ is a standard SQS queue, not a Lambda function.","D":"Without a DLQ, messages are deleted after exceeding maxReceiveCount, not retained indefinitely."},"source_url":"https://docs.aws.amazon.com/lambda/latest/dg/with-sqs.html","tags":["lambda","sqs","dlq","error-handling"],"verified":true},{"id":"03-e1f2g3h7","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Lambda event sources","difficulty":"hard","question":"A Lambda function is triggered by DynamoDB Streams to replicate changes to a secondary data store. The function is processing 1,000 records per second but keeps getting throttled. The DynamoDB table has 5 shards in the stream. Which approach increases Lambda throughput from this stream?","options":{"A":"Increase the DynamoDB table\'s provisioned write capacity","B":"Enable Enhanced Fan-Out on the DynamoDB Stream","C":"Increase the Lambda batch size and enable the parallelization factor on the event source mapping","D":"Switch from DynamoDB Streams to EventBridge Pipes"},"correct":"C","explanation":"To increase Lambda throughput from DynamoDB Streams, increase the batch size (up to 10,000 records per batch) so each invocation processes more records. Additionally, enable the Parallelization Factor (1-10) to allow multiple concurrent Lambda invocations per stream shard. With 5 shards and parallelization factor 10, you get up to 50 concurrent invocations processing the stream.","distractors":{"A":"Increasing DynamoDB write capacity increases the table\'s write throughput, not the Lambda processing throughput from the stream.","B":"Enhanced Fan-Out is a feature of Kinesis Data Streams, not DynamoDB Streams — it does not apply here.","D":"EventBridge Pipes can connect DynamoDB Streams to Lambda, but it does not inherently increase throughput over native DynamoDB Streams event source mapping."},"source_url":"https://docs.aws.amazon.com/lambda/latest/dg/with-ddb.html","tags":["lambda","dynamodb-streams","event-sources","throughput"],"verified":true},{"id":"03-f1g2h3i4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"API Gateway types and caching","difficulty":"easy","question":"A company wants to build a RESTful API that triggers Lambda functions. They require request/response transformation, usage plans with API keys, and built-in caching. Which API Gateway type should they use?","options":{"A":"HTTP API","B":"REST API","C":"WebSocket API","D":"GraphQL API via AppSync"},"correct":"B","explanation":"API Gateway REST API provides the full feature set including request/response transformation (mapping templates), usage plans with API keys and throttling, resource policies, and built-in response caching at the stage level. HTTP API is a newer, cheaper alternative but lacks usage plans, caching, and mapping templates.","distractors":{"A":"HTTP API is lower latency and cheaper than REST API but does not support usage plans with API keys, response caching, or request/response transformation via mapping templates.","C":"WebSocket API is for persistent bidirectional connections, not RESTful request-response patterns.","D":"AWS AppSync provides GraphQL APIs, not REST APIs, and is a different service entirely."},"source_url":"https://docs.aws.amazon.com/apigateway/latest/developerguide/http-api-vs-rest.html","tags":["api-gateway","rest-api","caching","usage-plans"],"verified":true},{"id":"03-f1g2h3i5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"API Gateway types and caching","difficulty":"medium","question":"An API Gateway REST API receives thousands of identical GET requests per second for product catalog data that changes only once per hour. Response times are slow due to backend Lambda cold starts. Which feature can reduce backend load and improve response times?","options":{"A":"Lambda Provisioned Concurrency only","B":"API Gateway response caching at the stage level","C":"CloudFront in front of API Gateway","D":"API Gateway usage plans with throttling"},"correct":"B","explanation":"API Gateway stage-level response caching caches responses for a specified TTL (up to 3600 seconds). Identical requests return the cached response without invoking the backend Lambda function. For data that changes hourly, a 3600-second TTL cache eliminates nearly all backend calls, dramatically reducing Lambda invocations and improving response times.","distractors":{"A":"Provisioned Concurrency eliminates Lambda cold starts but still invokes Lambda for every request — it does not reduce backend load for identical repeated requests.","C":"CloudFront also caches responses and can help, but it is an additional service layer. API Gateway\'s built-in cache is the most direct solution for this specific use case.","D":"Usage plans with throttling limit how many requests can be made — they do not cache responses or reduce backend load for legitimate traffic."},"source_url":"https://docs.aws.amazon.com/apigateway/latest/developerguide/api-gateway-caching.html","tags":["api-gateway","caching","performance","lambda"],"verified":true},{"id":"03-f1g2h3i6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"API Gateway types and caching","difficulty":"medium","question":"A company needs to build a real-time chat application where the server needs to push messages to connected clients without the client polling. Which API Gateway type supports this pattern?","options":{"A":"REST API with long polling","B":"HTTP API with server-sent events","C":"WebSocket API","D":"REST API with SQS integration"},"correct":"C","explanation":"API Gateway WebSocket API maintains persistent bidirectional connections between clients and the server. The server can push messages to connected clients at any time using the connection ID and the `@connections` endpoint. This enables real-time applications like chat, live dashboards, and gaming without client polling.","distractors":{"A":"REST API supports client-initiated requests only — the server cannot push to clients. Long polling is a client-side workaround, not a true push mechanism.","B":"HTTP API does not support server-sent events or persistent connections — it is a request-response API type.","D":"SQS integration with REST API is for asynchronous request queuing, not real-time server-to-client push."},"source_url":"https://docs.aws.amazon.com/apigateway/latest/developerguide/apigateway-websocket-api.html","tags":["api-gateway","websocket","real-time","push"],"verified":true},{"id":"03-f1g2h3i7","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"API Gateway types and caching","difficulty":"hard","question":"A company\'s API Gateway REST API is being abused by a single client making 10,000 requests per second, causing throttling for legitimate users. The company uses API keys for their customers. Which configuration prevents a single API key from consuming all available capacity?","options":{"A":"Set a regional throttling limit on the API Gateway stage","B":"Configure per-key throttling limits in a usage plan","C":"Enable WAF rate limiting on the API Gateway","D":"Set Lambda reserved concurrency to limit total invocations"},"correct":"B","explanation":"Usage plans in API Gateway allow you to set per-key throttling limits (requests per second and burst) and quotas (requests per day/week/month). By associating API keys with a usage plan, each key has its own rate limit. A misbehaving client is throttled at the key level before consuming the stage\'s overall capacity, protecting other legitimate API key holders.","distractors":{"A":"Stage-level throttling limits the total requests per second for all callers — it does not differentiate between API keys and does not prevent one key from consuming all capacity.","C":"WAF rate limiting can block IPs after a threshold, but it operates on IP addresses, not API keys, and adds cost. Per-key usage plans are the purpose-built solution.","D":"Lambda reserved concurrency limits backend Lambda invocations but does not differentiate between API keys at the API Gateway level."},"source_url":"https://docs.aws.amazon.com/apigateway/latest/developerguide/api-gateway-request-throttling.html","tags":["api-gateway","usage-plans","throttling","api-keys"],"verified":true},{"id":"03-g1h2i3j4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"DynamoDB indexes and DAX","difficulty":"easy","question":"A DynamoDB table uses `userId` as the partition key and `orderId` as the sort key. Queries by `userId` are fast, but the application also frequently queries orders by `status` (e.g., \'pending\', \'shipped\'). How can you enable efficient queries on `status` without modifying the primary key?","options":{"A":"Perform a full table scan with a filter expression on status","B":"Create a Global Secondary Index (GSI) with status as the partition key","C":"Create a Local Secondary Index (LSI) with status as the sort key","D":"Duplicate the table with status as the primary key"},"correct":"B","explanation":"A Global Secondary Index (GSI) allows you to query a DynamoDB table using an alternate key (partition key + optional sort key) different from the table\'s primary key. Creating a GSI with `status` as the partition key enables efficient queries for all orders with a given status. GSIs can be added to existing tables and have their own read/write capacity.","distractors":{"A":"A full table scan reads every item and applies a filter, consuming massive read capacity and performing poorly at scale — not appropriate for a frequent query pattern.","C":"An LSI uses the same partition key as the table (`userId`) but a different sort key. It enables querying orders by `status` for a specific user, but not all users globally.","D":"Duplicating the table doubles storage costs, requires custom synchronization logic, and is an anti-pattern when GSIs exist."},"source_url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/GSI.html","tags":["dynamodb","gsi","indexes","query"],"verified":true},{"id":"03-g1h2i3j5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"DynamoDB indexes and DAX","difficulty":"medium","question":"A DynamoDB table stores sensor readings with `deviceId` as partition key and `timestamp` as sort key. The application needs to query readings for a specific `deviceId` sorted by both `timestamp` AND `temperature` (for the same device). Which index type supports this?","options":{"A":"Global Secondary Index (GSI) with temperature as partition key","B":"Local Secondary Index (LSI) with temperature as sort key","C":"GSI with deviceId as partition key and temperature as sort key","D":"Composite sort key combining timestamp and temperature"},"correct":"B","explanation":"A Local Secondary Index (LSI) shares the same partition key as the base table (`deviceId`) but uses a different sort key (`temperature`). This allows querying readings for a specific device sorted by temperature. LSIs must be created at table creation time and share the same partition as the base table, enabling strongly consistent reads.","distractors":{"A":"A GSI with temperature as partition key would group all readings with the same temperature together across all devices, not per device.","C":"A GSI with deviceId+temperature would work similarly to an LSI for this query, but GSIs only support eventual consistency and must be provisioned separately. LSI is preferred when the partition key is the same.","D":"A composite sort key (e.g., `timestamp#temperature`) could work but complicates queries and does not support range queries on temperature independently."},"source_url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/LSI.html","tags":["dynamodb","lsi","indexes","sort-key"],"verified":true},{"id":"03-g1h2i3j6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"DynamoDB indexes and DAX","difficulty":"medium","question":"A gaming leaderboard application uses DynamoDB and experiences read-heavy traffic (95% reads, 5% writes) with average read latency of 5ms. The team needs to reduce read latency to under 1ms for frequently accessed leaderboard data. Which solution achieves this without architectural redesign?","options":{"A":"Enable DynamoDB Accelerator (DAX)","B":"Add a Global Secondary Index for leaderboard queries","C":"Switch to DynamoDB On-Demand capacity mode","D":"Increase provisioned read capacity units"},"correct":"A","explanation":"DynamoDB Accelerator (DAX) is a fully managed, in-memory cache for DynamoDB that delivers up to 10x read performance improvement, reducing response times from milliseconds to microseconds. DAX is API-compatible with DynamoDB — applications only need to change the endpoint from DynamoDB to the DAX cluster, with no other code changes. It is ideal for read-heavy workloads.","distractors":{"B":"GSIs improve query flexibility by allowing queries on different attributes, but they do not reduce read latency for existing queries — they add additional indexes to query.","C":"On-Demand capacity mode automatically adjusts capacity for variable workloads but does not improve read latency — it addresses capacity management, not speed.","D":"Increasing provisioned RCUs ensures requests are not throttled but does not reduce per-request latency for non-throttled reads — DynamoDB latency is already in the millisecond range."},"source_url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/DAX.html","tags":["dynamodb","dax","caching","latency"],"verified":true},{"id":"03-g1h2i3j7","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"DynamoDB indexes and DAX","difficulty":"hard","question":"A DynamoDB table has a GSI with `category` as partition key. The application has 10 categories but 90% of writes go to a single category (\'electronics\'). GSI writes are being throttled. What is the root cause and how should it be addressed?","options":{"A":"The GSI has insufficient provisioned write capacity; increase its WCUs","B":"Hot partition on the GSI — implement write sharding by appending a random suffix to the category key","C":"Switch the GSI to On-Demand capacity mode","D":"Use a LSI instead of a GSI to eliminate the throttling"},"correct":"B","explanation":"The root cause is a hot partition: 90% of writes land on the \'electronics\' partition key in the GSI, exceeding that partition\'s throughput (which is bounded to 3,000 WCU per partition regardless of total GSI capacity). Write sharding involves appending a random number (e.g., `electronics_1` through `electronics_10`) to distribute writes across multiple partitions. Reads must then fan out to all shards and merge results.","distractors":{"A":"Adding more WCUs helps with total throughput but does not fix the hot partition problem — DynamoDB limits each partition to 3,000 WCU, so a single key still throttles.","C":"On-Demand capacity mode auto-scales but still cannot exceed the per-partition limit — hot partitions throttle even with On-Demand if writes concentrate on one key.","D":"LSIs share the same partition key as the base table; they cannot change the partition key that is causing the hot partition issue in the GSI."},"source_url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/bp-partition-key-sharding.html","tags":["dynamodb","hot-partition","gsi","sharding"],"verified":true},{"id":"03-h1i2j3k4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Aurora Serverless v2","difficulty":"easy","question":"A development team runs a small internal application with a MySQL database that has unpredictable usage — idle most of the day but active for 2-hour bursts. They want to minimize costs while avoiding manual capacity management. Which database option is most appropriate?","options":{"A":"RDS MySQL with r5.2xlarge provisioned instance","B":"Aurora MySQL with Aurora Serverless v2","C":"DynamoDB with on-demand capacity","D":"Amazon Redshift Serverless"},"correct":"B","explanation":"Aurora Serverless v2 automatically scales compute capacity from 0.5 ACUs (Aurora Capacity Units) to the configured maximum within seconds, based on actual workload. During idle periods, it scales down to the minimum, significantly reducing costs. This is ideal for variable and unpredictable workloads like development databases where provisioning peak capacity would be wasteful.","distractors":{"A":"A provisioned r5.2xlarge instance runs 24/7 at full cost regardless of utilization — extremely inefficient for an idle-most-of-the-time workload.","C":"DynamoDB is a NoSQL database; if the application requires a relational MySQL database, DynamoDB is not a compatible replacement.","D":"Amazon Redshift Serverless is for analytical data warehousing workloads, not transactional MySQL application databases."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-serverless-v2.html","tags":["aurora","serverless","auto-scaling","cost"],"verified":true},{"id":"03-h1i2j3k5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Aurora Serverless v2","difficulty":"medium","question":"An Aurora Serverless v2 cluster is configured with a minimum of 0.5 ACUs and maximum of 128 ACUs. During a sudden traffic spike, response times increase before Aurora scales up. What is the reason for this delay and how can it be minimized?","options":{"A":"Aurora Serverless v2 requires a maintenance window to scale — schedule scaling during off-peak hours","B":"Aurora Serverless v2 scales in fine-grained steps and may take tens of seconds to reach peak capacity; set a higher minimum ACU to reduce scale-up time","C":"The cluster needs to failover to the writer instance before scaling, causing the delay","D":"Aurora Serverless v2 cannot scale beyond 64 ACUs; the 128 ACU configuration is invalid"},"correct":"B","explanation":"Aurora Serverless v2 scales rapidly (within seconds, not minutes) but starts from the configured minimum ACU (0.5 in this case). During a sudden spike, it scales up incrementally. Setting a higher minimum ACU ensures the cluster is pre-warmed with more capacity, reducing the time needed to reach the required scale during spikes. The trade-off is higher baseline cost.","distractors":{"A":"Aurora Serverless v2 scales automatically without maintenance windows or manual scheduling — scaling is continuous and transparent.","C":"Failover is for availability events (e.g., writer failure), not for scaling — scaling does not require failover.","D":"Aurora Serverless v2 supports up to 256 ACUs maximum — 128 ACUs is a valid configuration."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-serverless-v2.setting-capacity.html","tags":["aurora","serverless-v2","scaling","acu"],"verified":true},{"id":"03-h1i2j3k6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Aurora Serverless v2","difficulty":"hard","question":"A company uses an Aurora MySQL cluster with a provisioned writer and two provisioned readers. They want to add Aurora Serverless v2 readers to handle burst read traffic without provisioning excess permanent reader capacity. Is this possible, and what is the configuration called?","options":{"A":"Not possible — all instances in an Aurora cluster must be the same type (all provisioned or all serverless)","B":"Yes — this is a mixed-configuration cluster; add Serverless v2 reader instances alongside provisioned instances","C":"Yes — but only if the writer is also converted to Serverless v2 first","D":"Not possible — Aurora Serverless v2 does not support read replicas"},"correct":"B","explanation":"Aurora Serverless v2 supports mixed-configuration clusters where you can have provisioned instances (writer and/or readers) alongside Serverless v2 instances in the same cluster. Adding a Serverless v2 reader allows it to auto-scale during read traffic bursts while the provisioned readers handle the baseline load. This provides cost-efficient burst capacity without over-provisioning.","distractors":{"A":"This was a limitation of Aurora Serverless v1, not v2. Aurora Serverless v2 explicitly supports mixed clusters.","C":"The writer does not need to be Serverless v2 — any combination of provisioned and Serverless v2 instances is supported in the same cluster.","D":"Aurora Serverless v2 fully supports read replicas — Serverless v2 instances can be added as readers in any Aurora cluster."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-serverless-v2.requirements.html","tags":["aurora","serverless-v2","mixed-configuration","read-replicas"],"verified":true},{"id":"03-i1j2k3l4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"ElastiCache caching strategies","difficulty":"easy","question":"An e-commerce site uses ElastiCache Redis to cache product details. When a product is updated in the database, the cache should immediately reflect the change. Which caching strategy ensures the cache is always consistent with the database?","options":{"A":"Lazy loading (cache-aside)","B":"Write-through","C":"Write-behind (write-back)","D":"Read-through"},"correct":"B","explanation":"Write-through caching updates the cache whenever data is written to the database. Every write operation updates both the database and the cache simultaneously (or the application updates the cache after a successful DB write). This ensures the cache is always current and eliminates stale data. The trade-off is increased write latency and cache churn for infrequently read data.","distractors":{"A":"Lazy loading only populates the cache on cache misses (reading from DB then caching). After a database update, the cache still holds stale data until the TTL expires or the cache is manually invalidated.","C":"Write-behind writes to the cache first and asynchronously writes to the database later, which risks data loss and inconsistency — not a strong consistency strategy.","D":"Read-through is similar to lazy loading (cache handles the miss by reading from DB) but still requires TTL expiration or invalidation to reflect updates."},"source_url":"https://docs.aws.amazon.com/AmazonElastiCache/latest/red-ug/Strategies.html","tags":["elasticache","redis","caching","write-through"],"verified":true},{"id":"03-i1j2k3l5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"ElastiCache caching strategies","difficulty":"medium","question":"A social media application caches user profile data in ElastiCache Redis. Profile data is read millions of times per day but updated rarely. Cache misses cause slow database queries. Which strategy minimizes cache misses while managing memory efficiently?","options":{"A":"Write-through with no TTL","B":"Lazy loading with a 24-hour TTL","C":"Write-through with a 1-hour TTL","D":"No caching — use DynamoDB DAX instead"},"correct":"C","explanation":"Write-through ensures every profile update immediately refreshes the cache (no stale reads). A 1-hour TTL acts as a safety net for cache entries that were never explicitly invalidated (e.g., from direct DB changes or bugs). This combination maximizes cache hit rate for frequently read, rarely written data while preventing unbounded memory growth from orphaned cache entries.","distractors":{"A":"Write-through with no TTL fills memory with profiles of inactive users who may never be read again, wasting cache memory.","B":"Lazy loading with TTL means the first read after a profile update (or cache miss) hits the database — serving stale data for up to 24 hours after an update.","D":"DynamoDB DAX is only applicable if the data is stored in DynamoDB, not in a relational database. This answer changes the architecture rather than solving the caching strategy question."},"source_url":"https://docs.aws.amazon.com/AmazonElastiCache/latest/red-ug/Strategies.html","tags":["elasticache","redis","caching","ttl","write-through"],"verified":true},{"id":"03-i1j2k3l6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"ElastiCache caching strategies","difficulty":"medium","question":"A company needs to choose between ElastiCache Redis and ElastiCache Memcached for a session store that requires data persistence across cluster restarts, pub/sub messaging for notifications, and atomic operations. Which engine should they choose?","options":{"A":"Memcached — it is simpler and faster for session data","B":"Redis — it supports persistence, pub/sub, and atomic operations","C":"Either — both engines support all these features equally","D":"Neither — use DynamoDB for session storage instead"},"correct":"B","explanation":"ElastiCache Redis supports RDB snapshots and AOF for persistence (data survives cluster restarts), native pub/sub messaging for real-time notifications, and atomic operations via Lua scripts and MULTI/EXEC transactions. Redis also supports complex data structures (sorted sets, hashes, lists) useful for session data. Memcached supports none of these features.","distractors":{"A":"Memcached is multi-threaded and simpler, but it has no persistence (data lost on restart), no pub/sub, and no atomic operations — it cannot fulfill these requirements.","C":"Memcached does not support persistence, pub/sub, or atomic operations — the two engines are not equivalent in features.","D":"DynamoDB can store sessions but adds latency and cost compared to an in-memory store; the question asks about ElastiCache specifically."},"source_url":"https://docs.aws.amazon.com/AmazonElastiCache/latest/red-ug/SelectEngine.html","tags":["elasticache","redis","memcached","pub-sub","persistence"],"verified":true},{"id":"03-j1k2l3m4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"CloudFront distributions","difficulty":"easy","question":"A company hosts a static website on S3 and wants to serve it globally with low latency using CloudFront. They want to prevent direct public access to the S3 bucket while allowing CloudFront to read objects. Which CloudFront feature should they configure?","options":{"A":"CloudFront signed URLs for every request","B":"Origin Access Control (OAC) with S3 bucket policy allowing only the CloudFront distribution","C":"S3 Transfer Acceleration with CloudFront in front","D":"CloudFront Lambda@Edge to authenticate requests"},"correct":"B","explanation":"Origin Access Control (OAC) is the recommended mechanism to restrict S3 bucket access to only the CloudFront distribution. OAC uses SigV4 signing to authenticate CloudFront requests to S3. The S3 bucket policy grants GetObject permission only to the specific CloudFront distribution\'s OAC, blocking all other direct access. This replaces the older Origin Access Identity (OAI) with improved security and support for SSE-KMS.","distractors":{"A":"Signed URLs grant time-limited access to specific objects; they are for restricting access to specific users, not for the general CloudFront-to-S3 authorization pattern.","C":"S3 Transfer Acceleration speeds up direct S3 uploads/downloads using CloudFront edge locations but does not restrict public access to the bucket.","D":"Lambda@Edge can perform custom authentication but is a complex, expensive solution for what OAC achieves simply with a bucket policy."},"source_url":"https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/private-content-restricting-access-to-s3.html","tags":["cloudfront","s3","oac","security"],"verified":true},{"id":"03-j1k2l3m5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"CloudFront distributions","difficulty":"medium","question":"A media company uses CloudFront to deliver video content. They want to ensure only paying subscribers can access content — each user\'s URL should expire after 24 hours and be tied to their account to prevent link sharing. Which CloudFront feature implements this?","options":{"A":"CloudFront geographic restrictions","B":"CloudFront signed URLs with a custom policy specifying expiry and IP restriction","C":"S3 Object Lock with a 24-hour retention period","D":"CloudFront WAF rules blocking non-subscriber IPs"},"correct":"B","explanation":"CloudFront signed URLs allow you to create time-limited, optionally IP-restricted URLs. A custom policy lets you specify the exact expiry time (24 hours from generation), the resource URL, and optionally the client IP. The URL is signed with a CloudFront key pair. Only users with a valid signed URL can access the content — sharing the URL with others will fail after expiry or if IP restrictions apply.","distractors":{"A":"Geographic restrictions block access by country — they do not tie access to individual subscriber accounts or implement expiry.","C":"S3 Object Lock prevents deletion of objects for compliance purposes — it has no concept of subscriber access control or URL expiry.","D":"WAF rules can block IPs but cannot dynamically enforce per-user 24-hour access windows or prevent URL sharing."},"source_url":"https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/private-content-signed-urls.html","tags":["cloudfront","signed-urls","access-control","media"],"verified":true},{"id":"03-j1k2l3m6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"CloudFront distributions","difficulty":"medium","question":"A CloudFront distribution serves both static assets (images, JS, CSS) from S3 and dynamic API responses from an ALB. The static assets should be cached for 1 year, while API responses should never be cached. How should this be configured?","options":{"A":"Set a single CloudFront cache policy with TTL of 1 year for the distribution","B":"Create two cache behaviors: one for /api/* with TTL 0 and one for /* with TTL 1 year","C":"Configure cache headers on the S3 objects and disable caching on the ALB responses","D":"Use two separate CloudFront distributions — one for S3 and one for ALB"},"correct":"B","explanation":"CloudFront cache behaviors allow you to configure different caching rules for different URL path patterns. Create a cache behavior for `/api/*` with a cache policy setting TTL to 0 (no caching, or use the \'CachingDisabled\' managed policy), and a default behavior for `/*` with a TTL of 31,536,000 seconds (1 year) for static assets. CloudFront matches requests to behaviors in order of path pattern specificity.","distractors":{"A":"A single distribution-wide TTL of 1 year would cache API responses, returning stale data to users.","C":"While origin cache headers influence CloudFront behavior, CloudFront cache behaviors provide explicit, controlled configuration that does not rely on origin headers being set correctly.","D":"Two distributions work but are unnecessary — a single distribution with multiple cache behaviors is the purpose-built solution and reduces operational overhead."},"source_url":"https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/RequestAndResponseBehaviorForCustomOrigins.html","tags":["cloudfront","cache-behaviors","ttl","static-dynamic"],"verified":true},{"id":"03-j1k2l3m7","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"CloudFront distributions","difficulty":"hard","question":"A CloudFront distribution serves a personalized web application where each user sees different content based on a `session-id` cookie. Caching is disabled for all content. Users report that Lambda@Edge functions are adding 200ms of latency. Which approach reduces this overhead while preserving personalization?","options":{"A":"Replace Lambda@Edge with CloudFront Functions for lightweight header manipulation","B":"Move all Lambda@Edge logic to origin Lambda functions behind an ALB","C":"Enable CloudFront caching and use the session-id cookie as a cache key","D":"Switch to Global Accelerator instead of CloudFront"},"correct":"A","explanation":"CloudFront Functions execute JavaScript at the edge with sub-millisecond execution times and are 1/6th the cost of Lambda@Edge. They are ideal for lightweight operations like URL rewrites, header manipulation, and simple redirects that run at the viewer request/response events. If the Lambda@Edge functions are doing lightweight operations, CloudFront Functions eliminate the 200ms overhead while maintaining edge execution.","distractors":{"B":"Moving logic to origin Lambda functions behind an ALB removes edge execution entirely, adding round-trip latency to the origin rather than reducing overall latency.","C":"Caching with session-id as the cache key means each unique session gets its own cache entry — with millions of users, this provides no cache hit benefit and fills the cache with unique content.","D":"Global Accelerator improves network path to the origin using AWS backbone but does not execute code at the edge or support CloudFront-style edge functions."},"source_url":"https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/cloudfront-functions.html","tags":["cloudfront","cloudfront-functions","lambda-edge","latency"],"verified":true},{"id":"03-k1l2m3n4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Global Accelerator vs CloudFront","difficulty":"medium","question":"A company has a global user base accessing a real-time multiplayer game server running on EC2 instances in us-east-1. Users in Asia report high latency due to poor internet routing. The solution must support UDP and TCP (not HTTP). Which AWS service should be used?","options":{"A":"Amazon CloudFront","B":"AWS Global Accelerator","C":"Route 53 latency-based routing","D":"Amazon API Gateway with regional endpoints"},"correct":"B","explanation":"AWS Global Accelerator uses the AWS global network (not the public internet) to route traffic from users to the nearest AWS edge location, then routes over the private AWS backbone to the application in us-east-1. This avoids poor internet routing that causes high latency in Asia. Global Accelerator supports any TCP or UDP protocol, making it suitable for gaming (UDP) and real-time applications.","distractors":{"A":"CloudFront is an HTTP/HTTPS CDN that caches content at the edge — it does not support UDP and cannot proxy arbitrary TCP connections for gaming servers.","C":"Route 53 latency-based routing still sends user traffic over the public internet to the nearest region — it does not route over the AWS private backbone.","D":"API Gateway only supports HTTP/HTTPS REST and WebSocket APIs — it cannot handle UDP game traffic."},"source_url":"https://docs.aws.amazon.com/global-accelerator/latest/dg/what-is-global-accelerator.html","tags":["global-accelerator","cloudfront","udp","gaming","latency"],"verified":true},{"id":"03-k1l2m3n5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Global Accelerator vs CloudFront","difficulty":"medium","question":"A company serves a global API that returns personalized, non-cacheable JSON responses. Response times for users in Europe and Asia are 300ms higher than for US users due to internet routing variability. Which service improves global API response times without requiring content caching?","options":{"A":"CloudFront with caching disabled","B":"AWS Global Accelerator","C":"Route 53 geolocation routing to regional API copies","D":"S3 Transfer Acceleration"},"correct":"B","explanation":"AWS Global Accelerator provides two static anycast IP addresses and routes user traffic from the nearest edge location over the AWS private backbone to the origin, bypassing the public internet\'s variable routing. Because it works at the network layer (TCP/UDP), it improves latency for any application including non-cacheable API responses without requiring application changes or content caching.","distractors":{"A":"CloudFront with caching disabled still uses CloudFront edge locations to proxy requests, but for non-cacheable API traffic, CloudFront adds overhead compared to Global Accelerator. Global Accelerator is purpose-built for non-cacheable workloads.","C":"Route 53 geolocation routing could direct European users to a European API copy, but this requires deploying and maintaining the API in multiple regions.","D":"S3 Transfer Acceleration accelerates uploads to S3 using CloudFront edge locations — it does not apply to API responses."},"source_url":"https://docs.aws.amazon.com/global-accelerator/latest/dg/introduction-benefits-of-migrating.html","tags":["global-accelerator","api","latency","non-cacheable"],"verified":true},{"id":"03-k1l2m3n6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Global Accelerator vs CloudFront","difficulty":"hard","question":"A company uses AWS Global Accelerator with two endpoints: an ALB in us-east-1 (weight 50) and an ALB in eu-west-1 (weight 50). They want to shift 100% of traffic to us-east-1 for a maintenance window on eu-west-1 without changing DNS. Which action achieves this with the least disruption?","options":{"A":"Delete the eu-west-1 endpoint from the endpoint group","B":"Set the eu-west-1 endpoint weight to 0 in the Global Accelerator endpoint group","C":"Update Route 53 to point away from the Global Accelerator anycast IPs","D":"Set the eu-west-1 ALB\'s target group to have no healthy targets"},"correct":"B","explanation":"Global Accelerator endpoint weights control what percentage of traffic is directed to each endpoint within an endpoint group. Setting the eu-west-1 endpoint weight to 0 stops all traffic to that endpoint while keeping it configured. Traffic shifts to the remaining endpoints instantly without any DNS changes, since Global Accelerator uses static anycast IPs. Setting weight to 0 is the cleanest way to drain an endpoint without removing its configuration.","distractors":{"A":"Deleting the endpoint removes its configuration, requiring re-addition after maintenance and risking misconfiguration.","C":"Changing Route 53 would affect DNS TTL propagation delay and defeats the purpose of Global Accelerator\'s static anycast IPs.","D":"Removing healthy targets from the ALB target group causes 503 errors — traffic would fail rather than routing to us-east-1."},"source_url":"https://docs.aws.amazon.com/global-accelerator/latest/dg/about-endpoints-endpoint-weights.html","tags":["global-accelerator","endpoint-weights","traffic-shifting","maintenance"],"verified":true},{"id":"03-l1m2n3o4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Kinesis Data Streams vs SQS","difficulty":"easy","question":"A company needs to collect real-time clickstream events from a website and process them with multiple downstream consumers: one for real-time analytics, one for fraud detection, and one for personalization. Each consumer must read all events independently. Which service should be used?","options":{"A":"Amazon SQS Standard Queue","B":"Amazon SQS FIFO Queue","C":"Amazon Kinesis Data Streams","D":"Amazon SNS with SQS fan-out"},"correct":"C","explanation":"Kinesis Data Streams allows multiple consumers (via separate shard iterators or Enhanced Fan-Out) to read the same stream independently. Each consumer reads all records from its own position in the stream. Records are retained for up to 365 days, allowing consumers to read at their own pace. This is the canonical pattern for real-time event streaming with multiple independent consumers.","distractors":{"A":"SQS is a message queue — once a consumer reads and deletes a message, it is gone. Other consumers cannot read the same message. SQS does not support multiple independent consumers reading all messages.","B":"SQS FIFO provides ordering guarantees but still follows the queue model where a message is consumed once — multiple independent consumers cannot all read the same messages.","D":"SNS with SQS fan-out (one SNS topic, multiple SQS queues) does work for multiple consumers but adds more operational overhead. For true streaming with retention and replay, Kinesis is the appropriate choice."},"source_url":"https://docs.aws.amazon.com/streams/latest/dev/introduction.html","tags":["kinesis","sqs","streaming","fan-out","multiple-consumers"],"verified":true},{"id":"03-l1m2n3o5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Kinesis Data Streams vs SQS","difficulty":"medium","question":"A company processes orders where each order must be processed exactly once and in the order it was placed. Processing can take up to 10 minutes. Which queue service and configuration should they use?","options":{"A":"SQS Standard Queue with deduplication logic in the consumer","B":"SQS FIFO Queue with content-based deduplication and a visibility timeout greater than 10 minutes","C":"Kinesis Data Streams with sequence numbers for ordering","D":"SNS FIFO topic with SQS FIFO subscriber"},"correct":"B","explanation":"SQS FIFO queues guarantee exactly-once processing (using deduplication IDs) and message ordering within a message group. Content-based deduplication uses a SHA-256 hash of the message body to detect duplicates. The visibility timeout must be set longer than the maximum processing time (>10 minutes) to prevent the message from becoming visible again while being processed, which would cause duplicate processing.","distractors":{"A":"SQS Standard does not guarantee ordering (best-effort) and at-least-once delivery means duplicates can occur — requiring consumer-side deduplication adds complexity and may miss duplicates.","C":"Kinesis Data Streams provides ordering within a shard but does not provide exactly-once delivery natively — consumers must handle potential duplicate records. It is also designed for streaming, not transactional order processing.","D":"SNS FIFO to SQS FIFO adds an extra layer (SNS) that is only needed if multiple subscribers are required — for a single consumer, SQS FIFO directly is simpler and sufficient."},"source_url":"https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/FIFO-queues.html","tags":["sqs","fifo","ordering","exactly-once","visibility-timeout"],"verified":true},{"id":"03-l1m2n3o6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Kinesis Data Streams vs SQS","difficulty":"medium","question":"A Kinesis Data Stream has 4 shards processing 3,000 records per second (750/shard). The stream is approaching the per-shard limit of 1,000 records/second. What is the recommended way to increase stream throughput?","options":{"A":"Increase the record size to batch more data per record","B":"Enable Enhanced Fan-Out for additional consumers","C":"Use the UpdateShardCount API to reshard (split shards) to increase shard count","D":"Switch to SQS which has no throughput limits"},"correct":"C","explanation":"Each Kinesis shard supports 1,000 records/second for writes and 2 MB/second. To increase stream throughput, you reshard (split) existing shards to increase the total shard count. The `UpdateShardCount` API reshards the stream automatically. Doubling from 4 to 8 shards doubles write capacity to 8,000 records/second. Plan partition key distribution to ensure even spread across new shards.","distractors":{"A":"Increasing record size helps if the bottleneck is MB/s (not records/s), but the issue is records per second — batching records into fewer, larger records can help but requires application changes and is a workaround.","B":"Enhanced Fan-Out increases read throughput for consumers (2 MB/s per consumer per shard) — it does not increase write/ingest throughput.","D":"SQS does not support multiple independent consumers reading all messages and is not a streaming solution — it does not directly replace Kinesis for streaming workloads."},"source_url":"https://docs.aws.amazon.com/streams/latest/dev/kinesis-using-sdk-java-resharding.html","tags":["kinesis","shards","resharding","throughput"],"verified":true},{"id":"03-l1m2n3o7","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Kinesis Data Streams vs SQS","difficulty":"hard","question":"A Kinesis Data Stream consumer is a Lambda function that falls behind during traffic spikes, causing the iterator age to grow. Adding more Lambda concurrency does not help because there are only 5 shards. The team cannot add more shards due to partition key constraints. What can they do to increase Lambda throughput from this stream?","options":{"A":"Enable Kinesis Enhanced Fan-Out for the Lambda consumer","B":"Increase the Lambda parallelization factor for the event source mapping","C":"Switch to polling mode from push mode","D":"Use the Kinesis GetRecords API directly with multiple Lambda functions"},"correct":"B","explanation":"The Lambda Parallelization Factor (1-10) allows Lambda to invoke multiple concurrent executions per shard simultaneously. With 5 shards and parallelization factor 10, Lambda can use up to 50 concurrent executions to process the stream — a 10x increase in processing parallelism without adding shards. Records from the same shard are still delivered in order within each parallel execution sub-sequence.","distractors":{"A":"Enhanced Fan-Out provides dedicated 2 MB/s read throughput per consumer per shard — it increases read bandwidth but does not increase the processing parallelism per shard when Lambda is the bottleneck.","C":"Lambda already uses Kinesis event source mapping in polling mode — there is no \'push mode\' for Kinesis-to-Lambda. Lambda polls Kinesis shards.","D":"Using the GetRecords API directly requires custom consumer code, multiple Lambda functions, and shard management — this is more complex than the parallelization factor and does not solve the core throughput problem."},"source_url":"https://docs.aws.amazon.com/lambda/latest/dg/with-kinesis.html#services-kinesis-parallelization-factor","tags":["kinesis","lambda","parallelization-factor","throughput"],"verified":true},{"id":"03-m1n2o3p4","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Kinesis Data Firehose","difficulty":"easy","question":"A company collects application logs and wants to store them in Amazon S3 for long-term analysis with Athena. They want a fully managed solution that automatically batches and compresses logs before writing to S3, with no code to manage. Which service should they use?","options":{"A":"Kinesis Data Streams with a custom Lambda consumer writing to S3","B":"Amazon Kinesis Data Firehose","C":"Amazon MSK (Managed Streaming for Kafka) with a Kafka Connect S3 sink","D":"AWS Glue Streaming ETL job"},"correct":"B","explanation":"Amazon Kinesis Data Firehose is a fully managed service that automatically captures, transforms, and loads streaming data into destinations including S3, Redshift, OpenSearch, and Splunk. It handles batching, compression (gzip, snappy, zip), and encryption automatically. No ongoing code or infrastructure management is required — it is the simplest path for streaming logs to S3.","distractors":{"A":"Kinesis Data Streams + Lambda requires you to write and maintain the consumer Lambda function, handle batching logic, manage S3 writes, and configure error handling — significantly more operational overhead.","C":"Amazon MSK with Kafka Connect works for Kafka ecosystems but requires managing Kafka brokers, Kafka Connect workers, and connector configurations — far more complex for a simple log-to-S3 pipeline.","D":"AWS Glue Streaming ETL is for complex ETL transformations on streaming data; it is more expensive and complex than Firehose for simple log archival."},"source_url":"https://docs.aws.amazon.com/firehose/latest/dev/what-is-this-service.html","tags":["kinesis","firehose","s3","streaming","managed"],"verified":true},{"id":"03-m1n2o3p5","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Kinesis Data Firehose","difficulty":"medium","question":"A company uses Kinesis Data Firehose to load clickstream data into Amazon Redshift. The raw JSON events must be transformed to remove PII fields before loading. Which Firehose feature enables this transformation without external services?","options":{"A":"Firehose dynamic partitioning","B":"Firehose data transformation with Lambda","C":"Firehose format conversion (Parquet/ORC)","D":"Firehose record deaggregation"},"correct":"B","explanation":"Kinesis Data Firehose supports inline data transformation using Lambda functions. You configure a Lambda function as the transformation function in the Firehose delivery stream. Firehose automatically invokes the Lambda function with batches of records, and the function returns the transformed records (with PII removed). Failed records can go to an S3 error bucket. This is the standard pattern for real-time data cleansing within Firehose.","distractors":{"A":"Dynamic partitioning routes records to different S3 prefixes based on record field values (e.g., by date or customer ID) — it does not transform or remove fields.","C":"Format conversion transforms JSON into columnar formats (Parquet, ORC) using a Glue Data Catalog schema — it converts format but does not allow custom logic like PII removal.","D":"Record deaggregation is used with Kinesis Producer Library (KPL) aggregated records to split them before processing — it does not transform record content."},"source_url":"https://docs.aws.amazon.com/firehose/latest/dev/data-transformation.html","tags":["kinesis","firehose","lambda","transformation","pii"],"verified":true},{"id":"03-m1n2o3p6","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Kinesis Data Firehose","difficulty":"medium","question":"A company streams IoT sensor data to S3 via Kinesis Data Firehose. Athena queries on the S3 data are slow because files are stored as JSON and not partitioned by date. Which Firehose features can optimize Athena query performance?","options":{"A":"Enable Firehose server-side encryption and compression only","B":"Enable dynamic partitioning by timestamp and convert to Parquet format","C":"Increase the Firehose buffer size to 128 MB to create fewer, larger files","D":"Enable Firehose enhanced fan-out for faster delivery"},"correct":"B","explanation":"Two Firehose features dramatically improve Athena query performance: (1) Dynamic partitioning routes records to S3 prefixes like `year=2024/month=01/day=15/` based on timestamp, enabling Athena partition pruning to scan only relevant data. (2) Format conversion to Parquet creates columnar storage that Athena reads much faster than JSON. Together these can reduce query times and cost by 10-100x.","distractors":{"A":"Encryption improves security but not query performance. Compression reduces storage costs and improves scan throughput somewhat, but not as dramatically as columnar format + partitioning.","C":"Larger buffer sizes reduce the number of S3 files (good for avoiding small file problems) but do not solve the fundamental issues of JSON format and lack of partitioning.","D":"Firehose enhanced fan-out does not exist — Enhanced Fan-Out is a Kinesis Data Streams feature for consumers. Firehose delivers to destinations directly."},"source_url":"https://docs.aws.amazon.com/firehose/latest/dev/dynamic-partitioning.html","tags":["kinesis","firehose","athena","parquet","dynamic-partitioning"],"verified":true},{"id":"03-m1n2o3p7","version":1,"setId":"set-03-high-performing-architectures","domain":"High-Performing Architectures","topic":"Kinesis Data Firehose","difficulty":"hard","question":"A Kinesis Data Firehose delivery stream is configured with a 5-minute buffer interval and a 128 MB buffer size, whichever comes first. The data source generates 1 GB/minute of data. How frequently will Firehose write objects to S3?","options":{"A":"Every 5 minutes (buffer interval always takes precedence)","B":"Every 128 MB — approximately every 7.7 seconds","C":"Every 1 GB — Firehose waits to fill a 1 GB buffer","D":"Every 1 minute — Firehose scales buffer size automatically"},"correct":"B","explanation":"Firehose triggers a delivery when EITHER the buffer size OR the buffer interval threshold is reached, whichever comes first. At 1 GB/minute (≈17 MB/second), the 128 MB buffer fills in approximately 7.5 seconds — much faster than the 5-minute interval. So Firehose delivers to S3 approximately every 7.5 seconds (every 128 MB). This results in many small files; for Athena optimization, consider increasing buffer size to the maximum (128 MB is already max for most destinations) or using dynamic partitioning.","distractors":{"A":"The buffer interval only triggers delivery if the buffer size threshold has not already been reached — at 1 GB/min, the size threshold is hit every ~7.5 seconds, long before the 5-minute interval.","C":"Firehose has a maximum buffer size of 128 MB (for S3) — it does not accumulate 1 GB before delivering.","D":"Firehose does not auto-scale buffer size dynamically based on ingestion rate — the configured thresholds are fixed."},"source_url":"https://docs.aws.amazon.com/firehose/latest/dev/basic-deliver.html#s3-object-name","tags":["kinesis","firehose","buffer","s3","delivery"],"verified":true}]');export{e as default};